CREATE TYPE "UserRole" AS ENUM ('ADMIN','ORGANIZER','VIEWER');
CREATE TYPE "CompetitionStatus" AS ENUM ('DRAFT','PUBLISHED','COMPLETED','CANCELLED');
CREATE TYPE "CompetitionFormat" AS ENUM ('SINGLE_ROUND_ROBIN','DOUBLE_ROUND_ROBIN','KNOCKOUT','GROUP_STAGE');
CREATE TYPE "FixtureStatus" AS ENUM ('SCHEDULED','POSTPONED','PLAYED','CANCELLED');
CREATE TABLE users (id text PRIMARY KEY,email text UNIQUE NOT NULL,name text,password text NOT NULL,role "UserRole" NOT NULL DEFAULT 'ADMIN',"createdAt" timestamp(3) NOT NULL DEFAULT now(),"updatedAt" timestamp(3) NOT NULL DEFAULT now());
CREATE TABLE competitions (id text PRIMARY KEY,name text NOT NULL,description text,logo text,"primaryColor" text NOT NULL DEFAULT '#191B52',season text NOT NULL,"startDate" timestamp(3) NOT NULL,"endDate" timestamp(3) NOT NULL,status "CompetitionStatus" NOT NULL DEFAULT 'DRAFT',format "CompetitionFormat" NOT NULL DEFAULT 'DOUBLE_ROUND_ROBIN',"groupSize" integer NOT NULL DEFAULT 4,"createdBy" text NOT NULL REFERENCES users(id),"createdAt" timestamp(3) NOT NULL DEFAULT now(),"updatedAt" timestamp(3) NOT NULL DEFAULT now());
CREATE TABLE teams (id text PRIMARY KEY,name text NOT NULL,abbreviation text,logo text,"createdAt" timestamp(3) NOT NULL DEFAULT now(),"updatedAt" timestamp(3) NOT NULL DEFAULT now());
CREATE TABLE venues (id text PRIMARY KEY,name text UNIQUE NOT NULL,location text,capacity integer,"createdAt" timestamp(3) NOT NULL DEFAULT now(),"updatedAt" timestamp(3) NOT NULL DEFAULT now(),"homeTeamId" text UNIQUE REFERENCES teams(id) ON DELETE SET NULL);
CREATE TABLE competition_teams ("competitionId" text NOT NULL REFERENCES competitions(id) ON DELETE CASCADE,"teamId" text NOT NULL REFERENCES teams(id) ON DELETE CASCADE,"createdAt" timestamp(3) NOT NULL DEFAULT now(),PRIMARY KEY("competitionId","teamId"));
CREATE TABLE competition_venues ("competitionId" text NOT NULL REFERENCES competitions(id) ON DELETE CASCADE,"venueId" text NOT NULL REFERENCES venues(id) ON DELETE CASCADE,"createdAt" timestamp(3) NOT NULL DEFAULT now(),PRIMARY KEY("competitionId","venueId"));
CREATE TABLE fixtures (id text PRIMARY KEY,"competitionId" text NOT NULL REFERENCES competitions(id) ON DELETE CASCADE,"homeTeamId" text NOT NULL REFERENCES teams(id),"awayTeamId" text NOT NULL REFERENCES teams(id),"venueId" text REFERENCES venues(id) ON DELETE SET NULL,"matchDate" timestamp(3),"kickoffTime" text,matchday integer,"groupNumber" integer,status "FixtureStatus" NOT NULL DEFAULT 'SCHEDULED',notes text,version integer NOT NULL DEFAULT 1,"createdAt" timestamp(3) NOT NULL DEFAULT now(),"updatedAt" timestamp(3) NOT NULL DEFAULT now(),UNIQUE("competitionId","homeTeamId","awayTeamId",matchday));
CREATE TABLE audit_logs (id text PRIMARY KEY,"entityType" text NOT NULL,"entityId" text NOT NULL,action text NOT NULL,changes text,"performedBy" text NOT NULL REFERENCES users(id),"createdAt" timestamp(3) NOT NULL DEFAULT now());
CREATE INDEX fixtures_competition_matchday_idx ON fixtures("competitionId",matchday);
